const testXValue = 1.5;
const testYValue = 3.5;
await xStepperInput.click();
await xStepperInput.fill(String(testXValue));
await xStepperInput.press("Enter");
await page.waitForTimeout(2000);

// Re-query y stepper after x update re-render
const yStepperInputRefreshed = page.locator(`${panel} input[id="compose.sketchpad.app.design.panel.details.section.connection.y"]`).first();
await expect(yStepperInputRefreshed).toBeVisible();
// Use native value setter to bypass React controlled input issues after re-render
await yStepperInputRefreshed.click();
const yFilled = await yStepperInputRefreshed.evaluate((el: HTMLInputElement, val: number) => {
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, "value")?.set;
  if (!nativeInputValueSetter) return false;
  nativeInputValueSetter.call(el, String(val));
  el.dispatchEvent(new Event("input", { bubbles: true }));
  el.dispatchEvent(new Event("change", { bubbles: true }));
  return el.value === String(val);
}, testYValue);
console.log(`[Design] Y stepper native setter result: filled=${yFilled}`);
await yStepperInputRefreshed.press("Enter");
await page.waitForTimeout(2000);

